const $ = id => document.getElementById(id);
const shuffle = list => {const a=[...list];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const COOKIE_NAME='ai_sprout_v2';
const COOKIE_PATH=location.pathname.slice(0,location.pathname.lastIndexOf('/')+1)||'/';
let savedGame=null,restoring=false,profile={xp:0,wrong:[]};
try{const raw=document.cookie.split('; ').find(c=>c.startsWith(COOKIE_NAME+'='));let saved=raw?JSON.parse(decodeURIComponent(raw.slice(COOKIE_NAME.length+1))):null;
if(!saved){try{saved=JSON.parse(localStorage.getItem('ai-sprout-v1'));}catch{}}
if(saved&&Number.isSafeInteger(saved.xp)&&saved.xp>=0&&Array.isArray(saved.wrong)){profile={xp:saved.xp,wrong:[...new Set(saved.wrong.filter(id=>QUESTIONS.some(q=>q.id===id)))]};savedGame=saved.game;}}catch{}
function validGame(g){return g&&Array.isArray(g.ids)&&g.ids.length===10&&new Set(g.ids).size===10&&g.ids.every(id=>QUESTIONS.some(q=>q.id===id))&&Array.isArray(g.orders)&&g.orders.length===10&&g.orders.every(a=>Array.isArray(a)&&a.length===4&&[0,1,2,3].every(i=>a.includes(i)))&&Array.isArray(g.picks)&&g.picks.length<=10&&g.picks.every(i=>Number.isInteger(i)&&i>=0&&i<4)&&Number.isInteger(g.position)&&g.position>=0&&g.position<10&&(g.picks.length===g.position||g.picks.length===g.position+1)&&typeof g.finished==='boolean'&&(!g.finished||(g.position===9&&g.picks.length===10));}
function saveCookie(){if(restoring||!round.length)return;const game={ids:round.map(q=>q.id),orders:round.map(q=>q.choices.map(c=>c.index)),picks:history.map((h,i)=>round[i].options.indexOf(h.choice)),position,finished};try{document.cookie=COOKIE_NAME+'='+encodeURIComponent(JSON.stringify({...profile,game}))+'; Max-Age=31536000; Path='+COOKIE_PATH+'; SameSite=Lax'+(location.protocol==='https:'?'; Secure':'');}catch{}}
function initialize(){if(!validGame(savedGame)){newRound();return;}const g=savedGame;restoring=true;newRound();round=g.ids.map((id,i)=>{const q=QUESTIONS.find(q=>q.id===id);return {...q,choices:g.orders[i].map(index=>({index,text:q.options[index]}))};});render();g.picks.forEach((pick,i)=>{choose(round[position].choices.findIndex(c=>c.index===pick));submit();if(i<g.position||g.finished)submit();});restoring=false;persist();}

let sound=false,audioContext,engine,round=[],position=0,selected=-1,answered=false,roundXP=0,streak=0,bestStreak=0,history=[],finished=false;
function persist(){saveCookie();$('total-xp').textContent=profile.xp;$('wrong-count').textContent=profile.wrong.length;}
function tone(ok){if(!sound)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const o=audioContext.createOscillator(),g=audioContext.createGain();o.connect(g);g.connect(audioContext.destination);o.frequency.setValueAtTime(ok?520:220,audioContext.currentTime);o.frequency.exponentialRampToValueAtTime(ok?780:170,audioContext.currentTime+.15);g.gain.setValueAtTime(.06,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.25);o.start();o.stop(audioContext.currentTime+.26);}catch{}}
function newRound(){round=shuffle(QUESTIONS).slice(0,10).map(q=>({...q,choices:shuffle(q.options.map((text,index)=>({text,index})))}));position=0;roundXP=0;streak=0;bestStreak=0;history=[];finished=false;$('quiz').hidden=false;$('result').hidden=true;$('session-xp').textContent=0;$('streak').textContent=0;$('speech').innerHTML='嗨，我是小芽！<br>一起從好奇開始吧。';render();}
function progress(){const p=$('progress');p.replaceChildren();for(let i=0;i<10;i++){const dot=document.createElement('i');dot.className=history[i]?(history[i].ok?'done':'missed'):i===position?'current':'';p.append(dot);}p.setAttribute('aria-label',`已完成 ${history.length} / 10 題`);}
function render(){selected=-1;answered=false;$('feedback').hidden=true;$('submit').disabled=true;$('submit').innerHTML='確認答案 <span>→</span>';$('question-counter').textContent=`第 ${position+1} / 10 題`;const q=round[position];$('category').textContent=q.category;$('question').textContent=q.question;$('answers').replaceChildren();q.choices.forEach((choice,i)=>{const b=document.createElement('button');b.className='answer';b.setAttribute('aria-pressed','false');b.innerHTML=`<span class="letter">${'ABCD'[i]}</span><span class="answer-text"></span><span class="mark"></span>`;b.querySelector('.answer-text').textContent=choice.text;b.addEventListener('click',()=>choose(i));$('answers').append(b);});progress();persist();}
function choose(i){if(answered||finished||$('modal').open)return;selected=i;[...$('answers').children].forEach((b,j)=>{b.classList.toggle('selected',j===i);b.setAttribute('aria-pressed',String(i===j));});$('submit').disabled=false;}
function submit(){if(finished)return;if(answered){if(position===9){finish();return;}position++;render();return;}if(selected<0)return;answered=true;const q=round[position],ok=q.choices[selected].index===q.correct;streak=ok?streak+1:0;bestStreak=Math.max(bestStreak,streak);const points=ok?10+(streak>=3?5:0):0;roundXP+=points;if(!restoring){profile.xp+=points;if(!ok&&!profile.wrong.includes(q.id))profile.wrong.push(q.id);if(ok)profile.wrong=profile.wrong.filter(id=>id!==q.id);}history.push({id:q.id,ok,choice:q.choices[selected].text});persist();[...$('answers').children].forEach((b,i)=>{b.disabled=true;b.classList.remove('selected');if(q.choices[i].index===q.correct){b.classList.add('correct');b.querySelector('.mark').textContent='✓';}else if(i===selected){b.classList.add('wrong');b.querySelector('.mark').textContent='×';}});$('feedback').hidden=false;$('feedback').className='feedback'+(ok?'':' bad');$('feedback').replaceChildren();const title=document.createElement('strong');title.textContent=ok?`答對了！ +${points} XP${streak>=3?' · 連答獎勵 +5':''}`:'再學會一點點，也很棒！';$('feedback').append(title,document.createTextNode(q.explanation));$('submit').innerHTML=position===9?'查看成果 <span>→</span>':'下一題 <span>→</span>';$('session-xp').textContent=roundXP;$('streak').textContent=streak;$('speech').textContent=ok?(streak>=3?`連續答對 ${streak} 題！你的小芽正在長大！`:'太棒了！又收穫一點新知識。'):'沒關係，看看解析，我們一起學會！';progress();tone(ok);engine?.celebrate(ok);}
function finish(){finished=true;$('quiz').hidden=true;$('result').hidden=false;$('question-counter').textContent='已完成 10 / 10 題';const correct=history.filter(x=>x.ok).length;$('result').innerHTML=`<div class="result-hero"><div class="medal">${correct>=8?'🏆':'🌱'}</div><div class="eyebrow">LESSON COMPLETE</div><h2>${correct===10?'太棒了，十題全對！':'今天的知識，發芽了！'}</h2><p>${correct>=8?'你的 AI 基礎越來越扎實了。':'每一題都是養分，繼續保持好奇。'}</p><div class="result-numbers"><div><strong>${correct}/10</strong><small>答對題數</small></div><div><strong>+${roundXP}</strong><small>獲得 XP</small></div><div><strong>${bestStreak}</strong><small>最高連答</small></div></div><div class="result-actions"><button class="primary" id="again">再挑戰 10 題 →</button><button class="secondary" id="review-round">複習本次錯題 (${10-correct})</button></div></div>`;$('again').onclick=newRound;$('review-round').onclick=()=>showReview(history.filter(x=>!x.ok).map(x=>x.id),'本次錯題複習');engine?.celebrate(true);$('speech').textContent='任務完成！謝謝你今天和我一起成長。';persist();}
function showReview(ids,title='錯題筆記'){const body=$('modal-body');body.replaceChildren();if(!ids.length){const p=document.createElement('p');p.className='empty';p.textContent='🌱 目前沒有錯題！繼續練習，讓知識慢慢發芽。';body.append(p);}for(const id of ids){const q=QUESTIONS.find(x=>x.id===id);if(!q)continue;const item=document.createElement('div');item.className='review-item';const h=document.createElement('strong');h.textContent=q.question;const answer=document.createElement('p');answer.className='solution';answer.textContent='✓ '+q.options[q.correct];const explanation=document.createElement('p');explanation.textContent=q.explanation;item.append(h,answer,explanation);body.append(item);}openModal(title);}
function openModal(title){$('modal-title').textContent=title;$('modal').showModal();}
$('close-modal').onclick=()=>$('modal').close();$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('modal').close();}});
$('review-nav').onclick=()=>showReview(profile.wrong);$('guide-nav').onclick=()=>{$('modal-body').innerHTML='<div class="guide"><p>每天 10 題，把 AI 變得更熟悉。</p><ol><li>每局從 30 道入門題中隨機抽取 10 題，題目與選項順序都會改變。</li><li>選擇答案後按「確認答案」，查看正確答案與解析。</li><li>答對一題獲得 10 XP。連續答對第 3 題起，每題額外獲得 5 XP。</li><li>沒有時間限制，也不會因答錯而結束。完成 10 題後查看成果。</li><li>答錯的題目保留在錯題筆記，下次答對時自動移除。</li></ol><p class="guide-note">累積 XP、錯題筆記與本局進度透過此瀏覽器的 Cookie 儲存，效期為最後遊玩起一年。重新整理可接著玩；清除 Cookie、封鎖 Cookie 或使用其他瀏覽器將無法保留或共用進度。</p></div>';openModal('學習指南');};$('learn').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});$('submit').onclick=submit;$('sound').onclick=()=>{sound=!sound;$('sound').innerHTML=`♪ <span>音效${sound?'開':'關'}</span>`;$('sound').setAttribute('aria-label',sound?'關閉音效':'開啟音效');tone(true);};
document.addEventListener('keydown',e=>{if($('modal').open||finished||e.repeat)return;if(/^[1-4]$/.test(e.key)){e.preventDefault();choose(Number(e.key)-1);}if(e.key==='Enter'&&document.activeElement.tagName!=='BUTTON'){e.preventDefault();submit();}});
class SproutScene extends Phaser.Scene{constructor(){super('Sprout');}create(){engine=this;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const g=this.add.graphics();g.fillStyle(0xe0ead7,.7);g.fillEllipse(110,151,129,17);g.lineStyle(1,0xcbdcc4,.6);g.strokeCircle(110,91,65);g.strokeCircle(110,91,78);const bot=this.add.container(110,94);const b=this.add.graphics();b.fillStyle(0x478d6c);b.fillRoundedRect(-37,14,74,44,18);b.fillStyle(0x357957);b.fillRoundedRect(-29,48,21,13,6);b.fillRoundedRect(8,48,21,13,6);b.fillStyle(0x6caa85);b.fillRoundedRect(-56,16,17,34,8);b.fillRoundedRect(39,16,17,34,8);b.fillStyle(0x27674e);b.fillRoundedRect(-49,-37,98,70,24);b.fillStyle(0x83ba94);b.fillRoundedRect(-49,-43,98,70,24);b.fillStyle(0xeff8df);b.fillRoundedRect(-39,-33,78,48,17);b.fillStyle(0x2d654f);b.fillRoundedRect(-24,-18,9,14,4);b.fillRoundedRect(15,-18,9,14,4);b.lineStyle(2,0x2d654f);b.beginPath();b.arc(0,-6,7,0,Math.PI);b.strokePath();b.fillStyle(0xe7bba0,.8);b.fillEllipse(-27,0,12,6);b.fillEllipse(27,0,12,6);b.lineStyle(4,0x4a8f60);b.lineBetween(0,-43,0,-61);b.fillStyle(0x82b775);b.fillEllipse(-9,-65,23,12);b.fillStyle(0x599964);b.fillEllipse(10,-70,24,13);b.fillStyle(0xcce5b5);b.fillCircle(0,38,7);b.fillStyle(0xffffff,.8);b.fillCircle(0,38,3);bot.add(b);this.bot=bot;this.add.text(30,44,'✦',{fontSize:'19px',color:'#d2b66f'});this.add.text(184,117,'✧',{fontSize:'22px',color:'#9eb696'});if(!reduced)this.tweens.add({targets:bot,y:87,duration:1500,yoyo:true,repeat:-1,ease:'Sine.easeInOut'});persist();initialize();}celebrate(ok){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;if(!ok){this.tweens.add({targets:this.bot,angle:{from:-5,to:5},duration:110,yoyo:true,repeat:2,onComplete:()=>this.bot.setAngle(0)});return;}for(let i=0;i<12;i++){const p=this.add.rectangle(110,95,5,8,Phaser.Utils.Array.GetRandom([0xe2bc57,0x78ac81,0xa6cfb0]));this.tweens.add({targets:p,x:Phaser.Math.Between(20,200),y:Phaser.Math.Between(8,65),angle:Phaser.Math.Between(-180,180),alpha:0,duration:850,onComplete:()=>p.destroy()});}}}
if(window.Phaser){new Phaser.Game({type:Phaser.AUTO,width:220,height:176,parent:'game',transparent:true,scene:SproutScene,render:{antialias:true},audio:{noAudio:true},banner:false});}else{persist();initialize();$('speech').textContent='小芽暫時休息中，練習仍可繼續。';}
